p.x *= iResolution.x / iResolution.y;

vec3 ro = vec3(0.0, 0.0, 0.0);
vec3 rd = normalize(vec3(p, 1.5));

float steps = mod(iTime * 1.2, 9.0);
float d = clearance(ro, rd, steps);

