stages.helpers:
float sdSphere(vec3 p, float r) {
  return length(p) - r;
}

float map(vec3 p) {
  return sdSphere(p - vec3(0.0, 0.0, 3.0), 1.0);
}

float clearance(vec3 ro, vec3 rd, float steps) {
  float t = 0.0;
  for (int i = 0; i < 8; i++) {
    if (float(i) >= steps) break;
    t += map(ro + rd * t);
  }
  return map(ro + rd * t);
}

